def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Returns priority with which we want to add item to each bin.
    Args:
        item: Size of item to be added to the bin.
        bins: Array of capacities for each bin.
    Return:
        Array of same size as bins with priority score of each bin.
    """
    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    total_cap = np.sum(bins)
    if total_cap == 0:
        probs = np.ones_like(bins) / len(bins)
    else:
        probs = bins / total_cap
    entropy = -np.sum(probs * np.log(probs + 1e-12))
    score = entropy / (remaining + 1e-5)
    return np.where(valid, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Returns priority with which we want to add item to each bin.
    Args:
        item: Size of item to be added to the bin.
        bins: Array of capacities for each bin.
    Return:
        Array of same size as bins with priority score of each bin.
    """
    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    initial_sum = np.sum(bins)
    if initial_sum == 0:
        return np.where(valid, 0.0, -np.inf)
    fill_ratio = (bins - remaining) / initial_sum
    score = np.exp(-np.abs(fill_ratio - 0.5))
    return np.where(valid, score, -np.inf)

